import type { SheetData, SheetHeight, SheetItem, SheetPresentationOptions } from "../types";
import type { AnyComponent, ResolvedItem, SheetArg } from "./store-types";

const isString = (value: SheetArg): value is string => typeof value === "string";

const isSheetData = (value: SheetArg): value is SheetData =>
  typeof value === "object" && value !== null;

const hasAriaLabel = (value: SheetData): value is { ariaLabel: string } =>
  "ariaLabel" in value && typeof value.ariaLabel === "string";

const isSheetHeight = (value: unknown): value is SheetHeight => value === "full" || value === "fit";

const hasHeight = (value: SheetData): value is { height: SheetHeight } =>
  "height" in value && isSheetHeight(value.height);

export const toSheetData = (value: SheetArg): SheetData => (isSheetData(value) ? value : {});

export const isComponent = (value: SheetArg | AnyComponent): value is AnyComponent =>
  typeof value === "function";

const getComponentName = (component: AnyComponent): string | undefined => {
  const name = component.displayName ?? component.name;
  return name === "" ? undefined : name;
};

/**
 * Generate a unique sheet id. `crypto.randomUUID` is only available in
 * secure contexts, so fall back to a timestamp + random suffix on
 * non-secure origins (e.g. plain-HTTP LAN dev servers).
 */
export const generateSheetId = (): string => {
  if (globalThis.crypto?.randomUUID !== undefined) {
    return globalThis.crypto.randomUUID();
  }
  return `sheet-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
};

export const getStringArg = (value: SheetArg, name: string): string => {
  if (!isString(value)) {
    throw new TypeError(`Expected ${name} to be a string.`);
  }
  return value;
};

export const resolvePresentationOptions = (
  value: SheetArg,
): SheetPresentationOptions | undefined => {
  if (!isSheetData(value)) {
    return undefined;
  }
  const options: SheetPresentationOptions = {};
  if (hasAriaLabel(value)) {
    options.ariaLabel = value.ariaLabel;
  }
  if (hasHeight(value)) {
    options.height = value.height;
  }
  return options;
};

/** The presentation fields a resolved item carries. */
const toPresentation = (value: SheetArg): Pick<ResolvedItem, "ariaLabel" | "height"> => {
  const options = resolvePresentationOptions(value);
  return { ariaLabel: options?.ariaLabel, height: options?.height };
};
/**
 * Warn when a content component shares its name with a different component
 * already in the stack. That is almost always an inline arrow function
 * re-created on every render (`open(() => <MySheet />)`), which remounts the
 * Sheet and defeats `navigate()`'s same-type check.
 */
export const warnInlineComponent = (
  component: AnyComponent,
  stack: readonly SheetItem[],
  warnedNames: Set<string>,
): void => {
  const name = getComponentName(component);
  if (name === undefined || warnedNames.has(name)) {
    return;
  }
  const hasNamesake = stack.some(
    ({ type }) => isComponent(type) && type !== component && getComponentName(type) === name,
  );
  if (hasNamesake) {
    warnedNames.add(name);
    console.warn(
      `[stacksheet] A new component reference with name "${name}" was opened while a ` +
        "different reference with the same name is already in the stack. This usually " +
        "means you're passing an inline arrow function (e.g. open(() => <MySheet />)). " +
        "Define the component outside of render so navigate() can detect the same type.",
    );
  }
};

/**
 * Parse a sheet command's positional arguments: `(component, data, options?)`,
 * `(component, id, data, options?)` or `(type, id, data, options?)`.
 */
export const resolveArgs = (
  first: SheetArg,
  second: SheetArg,
  third: SheetArg,
  fourth?: SheetArg,
): ResolvedItem => {
  if (isComponent(first)) {
    if (isString(second)) {
      return {
        ...toPresentation(fourth),
        data: toSheetData(third),
        id: second,
        type: first,
      };
    }
    return {
      ...toPresentation(third),
      data: toSheetData(second),
      id: generateSheetId(),
      type: first,
    };
  }
  return {
    ...toPresentation(fourth),
    data: toSheetData(third),
    id: getStringArg(second, "sheet id"),
    type: getStringArg(first, "sheet type"),
  };
};
